contracts/AgentRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// @title AgentRegistry
/// @notice On-chain identity and state registry for Kite Garden agents.
///         Replaces external DID/Passport APIs with a fully self-contained
///         contract. Every agent lifecycle event is emitted and permanently
///         recorded on Kite L1 testnet.
contract AgentRegistry {

    // -------------------------------------------------------------------------
    // Types
    // -------------------------------------------------------------------------

    enum AgentStatus { Active, Frozen, Revoked }

    struct Agent {
        bytes32 agentId;
        string  name;
        address wallet;       // the address this agent pays from
        address owner;        // the human who controls this agent
        bytes32 baselineHash; // keccak256 of baseline parameters, committed on-chain
        uint256 baselineCommittedAt;
        AgentStatus status;
        uint256 registeredAt;
    }

    // -------------------------------------------------------------------------
    // Storage
    // -------------------------------------------------------------------------

    /// agentId => Agent
    mapping(bytes32 => Agent) private agents;

    /// owner address => list of agentIds they own
    mapping(address => bytes32[]) private ownerAgents;

    /// track all registered agentIds for enumeration
    bytes32[] private allAgentIds;

    // -------------------------------------------------------------------------
    // Events
    // -------------------------------------------------------------------------

    event AgentRegistered(
        bytes32 indexed agentId,
        string  name,
        address indexed wallet,
        address indexed owner,
        uint256 timestamp
    );

    event BaselineCommitted(
        bytes32 indexed agentId,
        bytes32 baselineHash,
        uint256 timestamp
    );

    event AgentFrozen(
        bytes32 indexed agentId,
        uint256 metricValue,   // scaled by 1e6 to avoid floats
        uint256 timestamp
    );

    event AgentRevoked(
        bytes32 indexed agentId,
        address indexed owner,
        uint256 timestamp
    );

    event AgentReauthorized(
        bytes32 indexed agentId,
        bytes32 newBaselineHash,
        uint256 timestamp
    );

    // -------------------------------------------------------------------------
    // Modifiers
    // -------------------------------------------------------------------------

    modifier onlyOwner(bytes32 agentId) {
        require(agents[agentId].owner == msg.sender, "AgentRegistry: not owner");
        _;
    }

    modifier agentExists(bytes32 agentId) {
        require(agents[agentId].registeredAt != 0, "AgentRegistry: agent not found");
        _;
    }

    modifier agentActive(bytes32 agentId) {
        require(agents[agentId].status == AgentStatus.Active, "AgentRegistry: agent not active");
        _;
    }

    // -------------------------------------------------------------------------
    // Write functions
    // -------------------------------------------------------------------------

    /// @notice Register a new agent. Derives agentId from name + wallet + timestamp.
    /// @param name       Human-readable agent name (e.g. "alice-expense-agent")
    /// @param wallet     The wallet address this agent makes payments from
    /// @return agentId   The unique bytes32 identifier for this agent
    function register(
        string calldata name,
        address wallet
    ) external returns (bytes32 agentId) {
        require(bytes(name).length > 0, "AgentRegistry: name required");
        require(wallet != address(0), "AgentRegistry: invalid wallet");

        agentId = keccak256(
            abi.encodePacked(name, wallet, msg.sender, block.timestamp)
        );

        require(agents[agentId].registeredAt == 0, "AgentRegistry: already registered");

        agents[agentId] = Agent({
            agentId:             agentId,
            name:                name,
            wallet:              wallet,
            owner:               msg.sender,
            baselineHash:        bytes32(0),
            baselineCommittedAt: 0,
            status:              AgentStatus.Active,
            registeredAt:        block.timestamp
        });

        ownerAgents[msg.sender].push(agentId);
        allAgentIds.push(agentId);

        emit AgentRegistered(agentId, name, wallet, msg.sender, block.timestamp);
    }

    /// @notice Commit a baseline hash on-chain. Called by the backend when the
    ///         behavioral baseline is first established or reset after a freeze.
    ///         Anyone can verify that the baseline has not changed by comparing
    ///         this hash against the parameters stored in the backend database.
    /// @param agentId      The agent to commit for
    /// @param baselineHash keccak256 of (mean, stddev, threshold, txCount, timestamp)
    function commitBaseline(
        bytes32 agentId,
        bytes32 baselineHash
    ) external agentExists(agentId) onlyOwner(agentId) {
        require(baselineHash != bytes32(0), "AgentRegistry: invalid hash");

        agents[agentId].baselineHash        = baselineHash;
        agents[agentId].baselineCommittedAt = block.timestamp;

        emit BaselineCommitted(agentId, baselineHash, block.timestamp);
    }

    /// @notice Freeze an agent when behavioral analysis detects divergence.
    ///         Called by the backend (owner's signing key) on DIVERGED verdict.
    ///         The metricValue is the correlation dimension or sample entropy
    ///         value that triggered the freeze, scaled by 1e6.
    /// @param agentId     The agent to freeze
    /// @param metricValue The diverged metric value * 1e6 (e.g. 2.87 => 2870000)
    function freezeAgent(
        bytes32 agentId,
        uint256 metricValue
    ) external agentExists(agentId) onlyOwner(agentId) agentActive(agentId) {
        agents[agentId].status = AgentStatus.Frozen;

        emit AgentFrozen(agentId, metricValue, block.timestamp);
    }

    /// @notice Permanently revoke an agent. Cannot be undone.
    /// @param agentId The agent to revoke
    function revokeAgent(
        bytes32 agentId
    ) external agentExists(agentId) onlyOwner(agentId) {
        require(
            agents[agentId].status != AgentStatus.Revoked,
            "AgentRegistry: already revoked"
        );

        agents[agentId].status = AgentStatus.Revoked;

        emit AgentRevoked(agentId, msg.sender, block.timestamp);
    }

    /// @notice Re-authorize a frozen agent after human review.
    ///         Commits a new baseline hash and sets status back to Active.
    /// @param agentId         The frozen agent to re-authorize
    /// @param newBaselineHash New baseline hash after human review and reset
    function reauthorize(
        bytes32 agentId,
        bytes32 newBaselineHash
    ) external agentExists(agentId) onlyOwner(agentId) {
        require(
            agents[agentId].status == AgentStatus.Frozen,
            "AgentRegistry: agent not frozen"
        );
        require(newBaselineHash != bytes32(0), "AgentRegistry: invalid hash");

        agents[agentId].status              = AgentStatus.Active;
        agents[agentId].baselineHash        = newBaselineHash;
        agents[agentId].baselineCommittedAt = block.timestamp;

        emit AgentReauthorized(agentId, newBaselineHash, block.timestamp);
    }

    // -------------------------------------------------------------------------
    // Read functions
    // -------------------------------------------------------------------------

    /// @notice Get full agent details
    function getAgent(bytes32 agentId)
        external
        view
        agentExists(agentId)
        returns (Agent memory)
    {
        return agents[agentId];
    }

    /// @notice Get all agentIds owned by an address
    function getAgentsByOwner(address owner)
        external
        view
        returns (bytes32[] memory)
    {
        return ownerAgents[owner];
    }

    /// @notice Get all registered agentIds (for indexing / dashboard)
    function getAllAgentIds() external view returns (bytes32[] memory) {
        return allAgentIds;
    }

    /// @notice Check if an agent is currently active
    function isActive(bytes32 agentId) external view returns (bool) {
        return agents[agentId].status == AgentStatus.Active;
    }

    /// @notice Total number of registered agents
    function totalAgents() external view returns (uint256) {
        return allAgentIds.length;
    }
}

contracts/AttractorGuard.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/**
 * @title AttractorGuard
 * @notice Behavioral session key revocation for autonomous AI agents on Kite AI
 * @dev Records gate decisions as on-chain events and stores agent registration data
 * 
 * Instead of blocking AI agents when they exceed a spending limit, AttractorGuard blocks them
 * when they stop behaving like themselves — by mapping every agent's real on-chain payment
 * history into phase space, computing its geometric complexity signature, and refusing to issue
 * the next Kite session key the moment that signature diverges from baseline.
 */
contract AttractorGuard {
    
    // ============ State Variables ============
    
    struct Agent {
        address owner;              // Human owner of the agent
        uint256 spendingLimit;      // Maximum spending limit per session key
        uint256 thresholdMultiplier;// Threshold sensitivity (σ multiplier, scaled by 100)
        uint256 transactionCount;   // Total transactions executed
        bool isActive;              // Is agent currently active
        bool isRevoked;             // Has agent been permanently revoked
        uint256 registeredAt;       // Registration timestamp
        uint256 lastActivityAt;     // Last transaction timestamp
    }
    
    struct GateDecision {
        bytes32 agentDID;
        bool issued;
        uint256 metricValue;        // Scaled by 1e18 for precision
        uint256 baselineValue;      // Scaled by 1e18 for precision
        uint256 amount;             // Transaction amount in wei
        address sessionKey;         // Session key issued (if issued)
        uint256 timestamp;
        uint256 blockNumber;
    }
    
    struct BaselineRecord {
        uint256 baselineValue;      // The baseline metric value
        uint256 timestamp;          // When baseline was set
        bool isActive;              // Is this the current baseline
        string reason;              // Why baseline was changed
    }
    
    // Mapping from agent DID to Agent struct
    mapping(bytes32 => Agent) public agents;
    
    // Mapping from agent DID to array of gate decision indices
    mapping(bytes32 => uint256[]) public agentDecisions;
    
    // Array of all gate decisions (for querying)
    GateDecision[] public decisions;
    
    // Mapping to track authorized backend addresses
    mapping(address => bool) public authorizedBackends;
    
    // Contract owner
    address public owner;
    
    // Total agents registered
    uint256 public totalAgents;
    
    // Total decisions logged
    uint256 public totalDecisions;
    
    // ============ NEW: Baseline History & Metadata ============
    
    mapping(bytes32 => string) public agentNames;
    mapping(bytes32 => string) public agentDescriptions;
    mapping(bytes32 => BaselineRecord[]) public baselineHistory;
    mapping(bytes32 => uint256) public currentBaselineIndex;
    mapping(bytes32 => uint256) public freezeCount;
    mapping(bytes32 => uint256) public lastFreezeTime;
    mapping(bytes32 => uint256) public decisionsApproved;
    mapping(bytes32 => uint256) public denialCount;
    
    // ============ Events ============
    
    event AgentRegistered(
        bytes32 indexed agentDID,
        address indexed owner,
        uint256 spendingLimit,
        uint256 timestamp
    );
    
    event SessionKeyIssued(
        bytes32 indexed agentDID,
        address indexed sessionKey,
        uint256 amount,
        uint256 metricValue,
        uint256 baselineValue,
        uint256 timestamp
    );
    
    event SessionKeyDenied(
        bytes32 indexed agentDID,
        uint256 amount,
        uint256 metricValue,
        uint256 baselineValue,
        uint256 timestamp
    );
    
    event AgentRevoked(
        bytes32 indexed agentDID,
        address indexed owner,
        uint256 timestamp
    );
    
    event BaselineReset(
        bytes32 indexed agentDID,
        uint256 newBaseline,
        uint256 timestamp
    );
    
    event AgentStatusChanged(
        bytes32 indexed agentDID,
        bool isActive,
        uint256 timestamp
    );
    
    event BackendAuthorized(
        address indexed backend,
        bool authorized,
        uint256 timestamp
    );
    
    event OwnershipTransferred(
        address indexed previousOwner,
        address indexed newOwner
    );
    
    event BaselineHistoryRecorded(
        bytes32 indexed agentDID,
        uint256 baselineValue,
        string reason,
        uint256 timestamp
    );
    
    event AgentFrozen(
        bytes32 indexed agentDID,
        uint256 freezeCount,
        string reason,
        uint256 timestamp
    );
    
    event AgentReauthorized(
        bytes32 indexed agentDID,
        uint256 newBaselineValue,
        string reason,
        uint256 timestamp
    );
    
    event AgentMetadataUpdated(
        bytes32 indexed agentDID,
        string name,
        string description,
        uint256 timestamp
    );
    
    // ============ Modifiers ============
    
    modifier onlyOwner() {
        require(msg.sender == owner, "Only owner can call");
        _;
    }
    
    modifier onlyAuthorizedBackend() {
        require(authorizedBackends[msg.sender], "Only authorized backend can call");
        _;
    }
    
    modifier agentExists(bytes32 agentDID) {
        require(agents[agentDID].owner != address(0), "Agent does not exist");
        _;
    }
    
    modifier agentNotRevoked(bytes32 agentDID) {
        require(!agents[agentDID].isRevoked, "Agent is revoked");
        _;
    }
    
    // ============ Constructor ============
    
    constructor() {
        owner = msg.sender;
        authorizedBackends[msg.sender] = true; // Owner is authorized by default
    }
    
    // ============ Agent Management Functions ============
    
    /**
     * @notice Register a new agent with AttractorGuard
     * @param agentDID The unique DID of the agent (format: did:kite:username.eth/agenttype/name-v1)
     * @param spendingLimit Maximum spending limit per session key in wei
     * @param thresholdMultiplier Threshold sensitivity (σ multiplier), scaled by 100 (e.g., 200 = 2.0σ)
     */
    function registerAgent(
        bytes32 agentDID,
        uint256 spendingLimit,
        uint256 thresholdMultiplier
    ) external returns (bool) {
        require(agents[agentDID].owner == address(0), "Agent already registered");
        require(spendingLimit > 0, "Spending limit must be > 0");
        require(thresholdMultiplier >= 100 && thresholdMultiplier <= 500, "Threshold must be between 1.0 and 5.0");
        
        agents[agentDID] = Agent({
            owner: msg.sender,
            spendingLimit: spendingLimit,
            thresholdMultiplier: thresholdMultiplier,
            transactionCount: 0,
            isActive: true,
            isRevoked: false,
            registeredAt: block.timestamp,
            lastActivityAt: block.timestamp
        });
        
        totalAgents++;
        
        emit AgentRegistered(agentDID, msg.sender, spendingLimit, block.timestamp);
        
        return true;
    }
    
    /**
     * @notice Log a gate decision (called by authorized backend)
     * @param agentDID The agent's DID
     * @param issued Whether the session key was issued
     * @param metricValue Current behavioral metric (scaled by 1e18)
     * @param baselineValue Baseline metric (scaled by 1e18)
     * @param amount Transaction amount
     * @param sessionKey Address of session key (zero address if denied)
     */
    function logDecision(
        bytes32 agentDID,
        bool issued,
        uint256 metricValue,
        uint256 baselineValue,
        uint256 amount,
        address sessionKey
    ) external onlyAuthorizedBackend agentExists(agentDID) agentNotRevoked(agentDID) returns (uint256) {
        
        Agent storage agent = agents[agentDID];
        agent.transactionCount++;
        agent.lastActivityAt = block.timestamp;
        
        GateDecision memory decision = GateDecision({
            agentDID: agentDID,
            issued: issued,
            metricValue: metricValue,
            baselineValue: baselineValue,
            amount: amount,
            sessionKey: sessionKey,
            timestamp: block.timestamp,
            blockNumber: block.number
        });
        
        uint256 decisionIndex = decisions.length;
        decisions.push(decision);
        agentDecisions[agentDID].push(decisionIndex);
        
        totalDecisions++;
        
        if (issued) {
            emit SessionKeyIssued(
                agentDID,
                sessionKey,
                amount,
                metricValue,
                baselineValue,
                block.timestamp
            );
        } else {
            emit SessionKeyDenied(
                agentDID,
                amount,
                metricValue,
                baselineValue,
                block.timestamp
            );
        }
        
        return decisionIndex;
    }
    
    /**
     * @notice Log decision with automatic statistics tracking
     */
    function logDecisionWithStats(
        bytes32 agentDID,
        bool issued,
        uint256 metricValue,
        uint256 baselineValue,
        uint256 amount,
        address sessionKey
    ) external onlyAuthorizedBackend agentExists(agentDID) agentNotRevoked(agentDID) returns (uint256) {
        
        Agent storage agent = agents[agentDID];
        agent.transactionCount++;
        agent.lastActivityAt = block.timestamp;
        
        GateDecision memory decision = GateDecision({
            agentDID: agentDID,
            issued: issued,
            metricValue: metricValue,
            baselineValue: baselineValue,
            amount: amount,
            sessionKey: sessionKey,
            timestamp: block.timestamp,
            blockNumber: block.number
        });
        
        uint256 decisionIndex = decisions.length;
        decisions.push(decision);
        agentDecisions[agentDID].push(decisionIndex);
        
        totalDecisions++;
        
        // Track statistics
        if (issued) {
            decisionsApproved[agentDID]++;
            emit SessionKeyIssued(
                agentDID,
                sessionKey,
                amount,
                metricValue,
                baselineValue,
                block.timestamp
            );
        } else {
            denialCount[agentDID]++;
            emit SessionKeyDenied(
                agentDID,
                amount,
                metricValue,
                baselineValue,
                block.timestamp
            );
        }
        
        return decisionIndex;
    }
    
    /**
     * @notice Revoke an agent permanently (only owner of agent)
     * @param agentDID The agent's DID
     */
    function revokeAgent(bytes32 agentDID) 
        external 
        agentExists(agentDID) 
        returns (bool) 
    {
        Agent storage agent = agents[agentDID];
        require(msg.sender == agent.owner, "Only agent owner can revoke");
        require(!agent.isRevoked, "Agent already revoked");
        
        agent.isRevoked = true;
        agent.isActive = false;
        
        emit AgentRevoked(agentDID, agent.owner, block.timestamp);
        
        return true;
    }
    
    /**
     * @notice Toggle agent active status (only owner of agent)
     * @param agentDID The agent's DID
     * @param isActive New active status
     */
    function setAgentStatus(bytes32 agentDID, bool isActive) 
        external 
        agentExists(agentDID) 
        agentNotRevoked(agentDID)
        returns (bool) 
    {
        Agent storage agent = agents[agentDID];
        require(msg.sender == agent.owner, "Only agent owner can change status");
        
        agent.isActive = isActive;
        
        emit AgentStatusChanged(agentDID, isActive, block.timestamp);
        
        return true;
    }
    
    /**
     * @notice Update agent spending limit (only owner of agent)
     * @param agentDID The agent's DID
     * @param newLimit New spending limit
     */
    function updateSpendingLimit(bytes32 agentDID, uint256 newLimit) 
        external 
        agentExists(agentDID) 
        returns (bool) 
    {
        Agent storage agent = agents[agentDID];
        require(msg.sender == agent.owner, "Only agent owner can update limit");
        require(newLimit > 0, "Limit must be > 0");
        
        agent.spendingLimit = newLimit;
        
        return true;
    }
    
    /**
     * @notice Reset baseline (emit event for off-chain tracking)
     * @param agentDID The agent's DID
     * @param newBaseline New baseline value (scaled by 1e18)
     */
    function resetBaseline(bytes32 agentDID, uint256 newBaseline) 
        external 
        agentExists(agentDID) 
        agentNotRevoked(agentDID)
        returns (bool) 
    {
        Agent storage agent = agents[agentDID];
        require(msg.sender == agent.owner, "Only agent owner can reset baseline");
        
        emit BaselineReset(agentDID, newBaseline, block.timestamp);
        
        return true;
    }
    
    // ============ View Functions ============
    
    /**
     * @notice Get agent information
     * @param agentDID The agent's DID
     */
    function getAgent(bytes32 agentDID) 
        external 
        view 
        returns (Agent memory) 
    {
        return agents[agentDID];
    }
    
    /**
     * @notice Get all decision indices for an agent
     * @param agentDID The agent's DID
     */
    function getAgentDecisions(bytes32 agentDID) 
        external 
        view 
        returns (uint256[] memory) 
    {
        return agentDecisions[agentDID];
    }
    
    /**
     * @notice Get decision by index
     * @param index Decision index
     */
    function getDecision(uint256 index) 
        external 
        view 
        returns (GateDecision memory) 
    {
        require(index < decisions.length, "Decision index out of bounds");
        return decisions[index];
    }
    
    /**
     * @notice Get recent decisions for an agent
     * @param agentDID The agent's DID
     * @param count Number of recent decisions to return
     */
    function getRecentDecisions(bytes32 agentDID, uint256 count) 
        external 
        view 
        returns (GateDecision[] memory) 
    {
        uint256[] memory indices = agentDecisions[agentDID];
        uint256 returnCount = count > indices.length ? indices.length : count;
        
        GateDecision[] memory recentDecisions = new GateDecision[](returnCount);
        
        for (uint256 i = 0; i < returnCount; i++) {
            uint256 index = indices[indices.length - 1 - i];
            recentDecisions[i] = decisions[index];
        }
        
        return recentDecisions;
    }
    
    /**
     * @notice Get total decisions count
     */
    function getTotalDecisions() external view returns (uint256) {
        return decisions.length;
    }
    
    /**
     * @notice Check if agent is authorized to transact
     * @param agentDID The agent's DID
     */
    function isAgentAuthorized(bytes32 agentDID) 
        external 
        view 
        returns (bool) 
    {
        Agent memory agent = agents[agentDID];
        return agent.owner != address(0) && agent.isActive && !agent.isRevoked;
    }
    
    // ============ Admin Functions ============
    
    /**
     * @notice Authorize a backend address to log decisions
     * @param backend Backend address
     * @param authorized Authorization status
     */
    function setBackendAuthorization(address backend, bool authorized) 
        external 
        onlyOwner 
        returns (bool) 
    {
        require(backend != address(0), "Invalid backend address");
        
        authorizedBackends[backend] = authorized;
        
        emit BackendAuthorized(backend, authorized, block.timestamp);
        
        return true;
    }
    
    /**
     * @notice Transfer ownership
     * @param newOwner New owner address
     */
    function transferOwnership(address newOwner) 
        external 
        onlyOwner 
        returns (bool) 
    {
        require(newOwner != address(0), "Invalid new owner");
        
        address previousOwner = owner;
        owner = newOwner;
        authorizedBackends[newOwner] = true;
        
        emit OwnershipTransferred(previousOwner, newOwner);
        
        return true;
    }
    
    // ============ NEW: Enhanced Functions ============
    
    /**
     * @notice Register agent with metadata and initial baseline
     */
    function registerAgentWithMetadata(
        bytes32 agentDID,
        string calldata name,
        string calldata description,
        uint256 spendingLimit,
        uint256 thresholdMultiplier,
        uint256 initialBaseline
    ) external returns (bool) {
        require(agents[agentDID].owner == address(0), "Agent already registered");
        require(spendingLimit > 0, "Spending limit must be > 0");
        require(thresholdMultiplier >= 100 && thresholdMultiplier <= 500, "Threshold must be between 1.0 and 5.0");
        
        agents[agentDID] = Agent({
            owner: msg.sender,
            spendingLimit: spendingLimit,
            thresholdMultiplier: thresholdMultiplier,
            transactionCount: 0,
            isActive: true,
            isRevoked: false,
            registeredAt: block.timestamp,
            lastActivityAt: block.timestamp
        });
        
        totalAgents++;
        
        agentNames[agentDID] = name;
        agentDescriptions[agentDID] = description;
        freezeCount[agentDID] = 0;
        lastFreezeTime[agentDID] = 0;
        decisionsApproved[agentDID] = 0;
        denialCount[agentDID] = 0;
        
        _recordBaseline(agentDID, initialBaseline, "initial");
        
        emit AgentRegistered(agentDID, msg.sender, spendingLimit, block.timestamp);
        emit AgentMetadataUpdated(agentDID, name, description, block.timestamp);
        
        return true;
    }
    
    /**
     * @notice Internal: Record baseline and maintain history
     */
    function _recordBaseline(
        bytes32 agentDID,
        uint256 baselineValue,
        string memory reason
    ) internal {
        if (currentBaselineIndex[agentDID] < baselineHistory[agentDID].length) {
            baselineHistory[agentDID][currentBaselineIndex[agentDID]].isActive = false;
        }
        
        BaselineRecord memory record = BaselineRecord({
            baselineValue: baselineValue,
            timestamp: block.timestamp,
            isActive: true,
            reason: reason
        });
        
        baselineHistory[agentDID].push(record);
        currentBaselineIndex[agentDID] = baselineHistory[agentDID].length - 1;
        
        emit BaselineHistoryRecorded(agentDID, baselineValue, reason, block.timestamp);
    }
    
    /**
     * @notice Reset baseline with reason
     */
    function resetBaselineWithReason(
        bytes32 agentDID,
        uint256 newBaseline,
        string calldata reason
    ) external agentExists(agentDID) agentNotRevoked(agentDID) returns (bool) {
        Agent storage agent = agents[agentDID];
        require(msg.sender == agent.owner, "Only agent owner");
        require(newBaseline > 0, "Baseline must be > 0");
        
        _recordBaseline(agentDID, newBaseline, reason);
        
        emit BaselineReset(agentDID, newBaseline, block.timestamp);
        
        return true;
    }
    
    /**
     * @notice Freeze agent with reason
     */
    function freezeAgentWithReason(
        bytes32 agentDID,
        string calldata reason
    ) external agentExists(agentDID) returns (bool) {
        Agent storage agent = agents[agentDID];
        require(msg.sender == agent.owner || authorizedBackends[msg.sender], "Not authorized");
        require(agent.isActive, "Agent not active");
        
        agent.isActive = false;
        freezeCount[agentDID]++;
        lastFreezeTime[agentDID] = block.timestamp;
        
        emit AgentFrozen(agentDID, freezeCount[agentDID], reason, block.timestamp);
        
        return true;
    }
    
    /**
     * @notice Reauthorize frozen agent with new baseline
     */
    function reauthorizeAgent(
        bytes32 agentDID,
        uint256 newBaseline,
        string calldata recoveryReason
    ) external agentExists(agentDID) agentNotRevoked(agentDID) returns (bool) {
        Agent storage agent = agents[agentDID];
        require(msg.sender == agent.owner, "Only agent owner");
        require(!agent.isActive, "Agent already active");
        
        agent.isActive = true;
        _recordBaseline(agentDID, newBaseline, recoveryReason);
        
        emit AgentReauthorized(agentDID, newBaseline, recoveryReason, block.timestamp);
        
        return true;
    }
    
    /**
     * @notice Get baseline history for an agent
     */
    function getBaselineHistory(bytes32 agentDID)
        external
        view
        returns (BaselineRecord[] memory)
    {
        return baselineHistory[agentDID];
    }
    
    /**
     * @notice Get current active baseline
     */
    function getCurrentBaseline(bytes32 agentDID)
        external
        view
        returns (uint256 value, uint256 timestamp, string memory reason)
    {
        uint256 idx = currentBaselineIndex[agentDID];
        if (baselineHistory[agentDID].length > idx) {
            BaselineRecord memory record = baselineHistory[agentDID][idx];
            return (record.baselineValue, record.timestamp, record.reason);
        }
        return (0, 0, "");
    }
    
    /**
     * @notice Get agent statistics
     */
    function getAgentStats(bytes32 agentDID)
        external
        view
        returns (
            uint256 approvalsCount,
            uint256 denialCounts,
            uint256 freezeCounts,
            string memory name,
            string memory description
        )
    {
        return (
            decisionsApproved[agentDID],
            denialCount[agentDID],
            freezeCount[agentDID],
            agentNames[agentDID],
            agentDescriptions[agentDID]
        );
    }
}

